# 网络流学习笔记
## 最大流最小割
结论：图的最大流的流量就是最小割。  
证明不会。  
::::success[dinic]
```cpp
#include <bits/stdc++.h>
#define eb emplace_back
#define int long long
using namespace std;
const int N = 660;
struct Node{
	int to;
	int val;
	int rev;
};
vector<Node> e[N];
int n, m, s, t, ans, dep[N], cur[N];
bool bfs(){
	queue<int> q;
	q.push(s);
	memset(dep, -1, sizeof dep);
	dep[s] = 0;
	while(!q.empty()){
		int u = q.front();
		q.pop();
		for(auto v : e[u]){
			if(dep[v.to] == -1 && v.val){
				dep[v.to] = dep[u] + 1;
				q.push(v.to);				
			}
		}
	}
	memset(cur, 0, sizeof cur);
	return (dep[t] != -1);
}
int dfs(int u, int flow){
	if(u == t) return flow;
	int res = 0;
	for(int &i = cur[u]; i < e[u].size(); i++){
		Node v = e[u][i];
		if(dep[v.to] == dep[u] + 1 && v.val){
			int tmp = 0;
			tmp = dfs(v.to, min(flow - res, v.val));
			if(tmp){
				e[u][i].val -= tmp;
				e[v.to][v.rev].val += tmp;
				res += tmp;
				if(res == flow) break;		
			}else dep[v.to] = -1;
		}
	}
	return res;
}
void dinic(){
	while(bfs()){ans += dfs(s, 1e18);}
}
signed main(){
//	freopen(".in", "r", stdin);
//	freopen(".out", "w", stdout);
	cin.tie(0);
	std::ios::sync_with_stdio(0);
	cin >> n >> m >> s >> t;
	for(int i = 1; i <= m; i++){
		int u, v, w;
		cin >> u >> v >> w;
		int su = e[u].size(), sv = e[v].size();
		e[u].eb(Node{v, w, sv});
		e[v].eb(Node{u, 0, su});
	}
	dinic();
	cout << ans << "\n";
	return 0;
}
```
