```cpp
#include <bits/stdc++.h>
#define int long long
using namespace std;
const int N = 1100, inf = 1e15;
int n, k, a[N][N], dp[N][N * 5]; //前 i 个格子能凑出来的前 rank 大美丽值
struct Node{
    int val;
    int id;
    int rk;
};
bool operator<(const Node &x, const Node &y){
    return x.val < y.val;
}
priority_queue<Node> q;
signed main(){
    int T;
    cin >> T;
    while(T--){
        cin >> n >> k;
        for(int i = 1; i <= n; i++) for(int j = i; j <= n; j++) cin >> a[i][j];
        for(int i = 0; i <= n + 5; i++) for(int rank = 1; rank <= k + 5; rank++) dp[i][rank] = -inf;
        dp[0][1] = 0;
        for(int i = 1; i <= n; i++){
            while(!q.empty()) q.pop();
            for(int rank = 1; rank <= k; rank++) q.push(Node{dp[i - 1][rank], 0, 114514});
            for(int j = 1; j <= i; j++) q.push(Node{dp[max(j - 2, 0LL)][1] + a[j][i], j, 1});
            for(int rank = 1; rank <= k; rank++){
                Node tmp = q.top();
                q.pop();
                dp[i][rank] = tmp.val;
                if(tmp.id) q.push(Node{dp[max(tmp.id - 2, 0LL)][tmp.rk + 1] + a[tmp.id][i], tmp.id, tmp.rk + 1});
            }
        }
        for(int rank = 1; rank <= k; rank++) cout << dp[n][rank] << " ";
        cout << "\n";
    }
    return 0;
}
