[AT_abc143_f](https://www.luogu.com.cn/problem/AT_abc143_f)  
完蛋了，对着 dp 和 ds 想了 inf 分钟，一看标签怎么是二分、前缀和、双指针！？  
思路就是先搞个桶 b 存每个数出现次数，然后倒序排序。  
从后往前枚举 $x$ 找到第一次在后缀 $[x, cnt]$ 里选取 $k-x+1$ 个，选到不能再选的时候前 $x-1$ 个仍然可以继续选的 $x$ 的取值，答案就是在后缀 $[x, cnt]$ 里选 $k - x + 1$ 个能选的最多次数。  
即：希望找出最大的使得 $\frac{1}{k-x+1}\sum_{i=x}^{cnt}b_i < b_{x-1}$ 的 $x$。  
即 $\sum_{i=x}^{cnt}b_i < (k-x+1) b_{x-1}$。  
相邻两个不等式的变化量作差就能知道这个式子是单调的，做一下后缀和对于每一个 $k$ 二分答案找即可，最终答案是 $\frac{1}{k-x+1}\sum_{i=x}^{cnt}b_i$。
::::success[code]
```cpp
#include <bits/stdc++.h>
#define int long long
using namespace std;
const int N = 3e5 + 10;
int n, k, b[N], cnt, sum[N];
bool cmp(int x, int y){
	return x > y;
}
bool check(int x, int k){
	if(x == 1) return 1;  
	return sum[x] < (k - x + 1) * b[x - 1];
}
signed main(){
//	freopen(".in", "r", stdin);
//	freopen(".out", "w", stdout);
	cin.tie(0);
	std::ios::sync_with_stdio(0);
	cin >> n;
	for(int i = 1; i <= n; i++){
		int x;
		cin >> x;
		if(!b[x]) cnt++;
		b[x] ++;
	}
	sort(b + 1, b + n + 1, cmp);
	for(int i = cnt; i >= 1; i--) sum[i] = sum[i + 1] + b[i];
	for(int k = 1; k <= n; k++){
		if(k > cnt) cout << 0 << "\n";
		else if(k == cnt) cout << b[cnt] << "\n";
		else{
			int l = 1, r = k, ans = 0;
			while(l <= r){
				int mid = l + r >> 1;
				if(check(mid, k)){
					ans = mid;
					l = mid + 1;
				}else{
					r = mid - 1;
				}
			}
			cout << sum[ans] / (k - ans + 1) << "\n";
		}
	}
	return 0;
}
```
