#include <bits/stdc++.h>
#define int long long
#define lowbit(x) x&-x
using namespace std;
const int N = 5e4 + 10;
int vis[N], n, xs[N], ys[N];
struct Node{
	int x, y, rx, ry, id, dp, oid;
	double cnt;
}ls[N], a[N];
struct Tree{
	int mx;
	double sum;
}tr[N];
void update(int x, int y, double cnt){
	while(x <= n){
		if(y > tr[x].mx) tr[x].mx = y, tr[x].sum = cnt; 
		else if(y == tr[x].mx) tr[x].sum += cnt;
		x += lowbit(x);
	}
}
void cl(int x){
	while(x <= n){
		tr[x].mx = tr[x].sum = 0;
		x += lowbit(x);
	}
}
Tree query(int x){
	Tree res = {0, 0};
	while(x){
		if(res.mx < tr[x].mx) res.mx = tr[x].mx, res.sum = tr[x].sum;
		else if(res.mx == tr[x].mx) res.sum += tr[x].sum;
		x -= lowbit(x);
	}
	return res;
}
bool cmp1(Node x, Node y){
	return x.x < y.x;
}
bool cmp2(Node x, Node y){
	return x.oid < y.oid;
}
void cdq(int l, int r){
	if(l == r) return;
	int mid = l + r >> 1;
	cdq(l, mid);
	for(int i = mid + 1; i <= r; i++){
		ls[i] = a[i];
		ls[i].id = i;
	}
	sort(ls + mid + 1, ls + r + 1, cmp1);
	int pl = l, pr;
	int idx = 0;
	for(pr = mid + 1; pr <= r; pr++){
		while(pl <= mid && a[pl].x <= ls[pr].x){
			update(a[pl].y, a[pl].dp, a[pl].cnt); 
			vis[++idx] = a[pl].y;
			pl++;
		}
		Tree tmp = query(ls[pr].y);
		if(tmp.mx + 1 > ls[pr].dp) ls[pr].dp = tmp.mx + 1, ls[pr].cnt = tmp.sum;
		else if(tmp.mx + 1 == ls[pr].dp) ls[pr].cnt += tmp.sum;
	}
	for(int i = mid + 1; i <= r; i++) a[ls[i].id] = ls[i];
	for(int i = 1; i <= idx; i++) cl(vis[i]);
	cdq(mid + 1, r);
	pl = l, pr = mid + 1;
	idx = 0;
	while(pl <= mid && pr <= r){
		if(a[pl].x <= a[pr].x) ls[++idx] = a[pl++];
		else ls[++idx] = a[pr++];
	}
	while(pl <= mid) ls[++idx] = a[pl++];
	while(pr <= r) ls[++idx] = a[pr++];
	for(int i = 1; i <= idx; i++) a[l + i - 1] = ls[i];
}
int f[2][N];
double g[2][N];
signed main(){
//	freopen(".in", "r", stdin);
//	freopen(".out", "w", stdout);
   	ios::sync_with_stdio(0);
    cin.tie(0);
    cin >> n;
    for(int i = 1; i <= n; i++){
        cin >> a[i].rx >> a[i].ry;
        a[i].oid = i;
        xs[i] = a[i].rx;
        ys[i] = a[i].ry;
        a[i].cnt = 1;
        a[i].dp = 1;
    }
    sort(xs + 1, xs + n + 1);
    int sizx = unique(xs + 1, xs + n + 1) - xs - 1;
    sort(ys + 1, ys + n + 1);
    int sizy = unique(ys + 1, ys + n + 1) - ys - 1;
    for(int i = 1; i <= n; i++){
        a[i].x = lower_bound(xs + 1, xs + sizx + 1, a[i].rx) - xs;
        a[i].y = lower_bound(ys + 1, ys + sizy + 1, a[i].ry) - ys;		
		a[i].x = sizx - a[i].x + 1;
		a[i].y = sizy - a[i].y + 1;
    }
    cdq(1, n);
    sort(a + 1, a + n + 1, cmp2);
    for(int i = 1; i <= n; i++){
    	f[0][i] = a[i].dp;
    	g[0][i] = a[i].cnt;
	} 
	for(int i = 1; i <= n/2; i++) swap(a[i], a[n - i + 1]);
	for(int i = 1; i <= n; i++){
		a[i].dp = a[i].cnt = 0;
		a[i].oid = i;
		a[i].x = sizx - a[i].x + 1;
		a[i].y = sizy - a[i].y + 1;
        a[i].cnt = 1;
        a[i].dp = 1;
	}
	cdq(1, n);
    sort(a + 1, a + n + 1, cmp2);
	for(int i = 1; i <= n; i++){
		f[1][n - i + 1] = a[i].dp;
		g[1][n - i + 1] = a[i].cnt;
	}
	int mx = 0;
	double sum = 0;
	for(int i = 1; i <= n; i++){
		if(f[0][i] > mx) sum = g[0][i], mx = f[0][i];
		else if(f[0][i] == mx) sum += g[0][i];
	}
	cout << mx << "\n";
	for(int i = 1; i <= n; i++){
		if(f[0][i] + f[1][i] - 1 == mx){
			cout << g[0][i] * g[1][i] / sum << " ";
		}else{
			cout << 0 << " ";
		}
	}
	return 0;
}
