#include <bits/stdc++.h>
#define int long long
using namespace std;
const int mod = 998244353;
struct Node{
	int a[25][25];
	void init1(){ for(int i = 1; i <= 24; i++) for(int j = 1; j <= 24; j++) a[i][j] = (i == j); }
	void init2(){ for(int i = 1; i <= 24; i++) for(int j = 1; j <= 24; j++) a[i][j] = 0; }
}base, ans;
Node operator *(const Node &x, const Node &y){
	Node ans;
	for(int i = 1; i <= 24; i++){
		for(int j = 1; j <= 24; j++){
			ans.a[i][j] = 0;
			for(int k = 1; k <= 24; k++) ans.a[i][j] = (ans.a[i][j] + x.a[i][k] * y.a[k][j] % mod) % mod;
		}
	}
	return ans;
}
Node ksm1(Node b, int p){
	Node res;
	res.init1();
	while(p){
		if(p & 1){
			res = res * b;
		}
		b = b * b;
		p >>= 1;
	}
	return res;
}
int ksm(int a, int b){
	int res = 1;
	while(b){
		if(b & 1) res = res * a % mod;
		a = a * a % mod;
		b >>= 1;
	}
	return res;
}
char c[40];
int p[40], mul[40], ivp[40];
signed main(){
//	freopen(".in", "r", stdin);
//	freopen(".out", "w", stdout);
	cin.tie(0);
