	int n, x, y;
	cin >> n >> x >> y;
	int i100 = ksm(100, mod - 2);
	int w = 1, px = x * i100 % mod, py = y * i100 % mod, ipx = (100 - x + mod) * i100 % mod, ipy = (100 - y + mod) * i100 % mod;
	ans.init2();
	for(int i = 1; i <= 24; i++){
		cin >> c[i];
		if(c[i] == 'T') ivp[i] = ipx, p[i] = px;
		else ivp[i] = ipy, p[i] = py;
		w = w * ivp[i] % mod;
		mul[i] = w;
	}
	mul[0] = 1;
	for(int i = 1; i <= 24; i++){
		for(int j = 1; j <= 24; j++){
			base.a[i][j] = mul[24] * ksm(mul[i], mod - 2) % mod * mul[j - 1] % mod * p[j] % mod * ksm(1 - w + mod, mod - 2) % mod;
			if(j > i) base.a[i][j] = (base.a[i][j] + mul[j - 1] * ksm(mul[i], mod - 2) % mod * p[j] % mod) % mod;
		}
	}
	for(int i = 1; i <= 24; i++) ans.a[1][i] = base.a[24][i];
	ans = ans * ksm1(base, n - 1);
	int res = 0;
	for(int i = 1; i <= 24; i++){
		if(c[i] == 'A') res = (res + ans.a[1][i]) % mod;
	}
	cout << res;
	return 0;
}
