		int sum = 0;
		for(int t = 0; t <= min(K, mx_dep[k] - dep[k]); t++) sum = (sum + dp[k][t][0]) % mod;
		for(int j = 0; j <= min(K, mx_dep[u] - dep[u]); j++){
			for(int t = 0; t <= min(K - j - 1, mx_dep[k] - dep[k]); t++){
