			if(a[j].y > a[i].y) continue;
			f[i] = (f[i] - f[j] * js(a[j], a[i]) % mod + mod) % mod;
		}
		ans = (ans - f[i] * js(a[i], t) % mod + mod) % mod;
	}
	cout << (ans + mod) % mod;
	return 0;
}
