#### [CF1622D Shuffle](https://www.luogu.com.cn/problem/CF1622D)
这太困难了长官，被绿题硬控 1h。做完一看 $n\le 5000$ 我怎么写的是 $\mathcal{O}(n)$ 的算法啊，这太奇异搞笑了你知道吗。

> 注意 $10-3 \ne 6$ 啊 TAT  

考虑对于一个包含恰好 $k$ 个 $1$ 的极长连续段 $[l,r]$ 进行重排，一共有 $\binom{r - l + 1}{k}$ 种情况，但是直接全部加起来会算重。设该段中最后一个 $1$ 出现在位置 $p$，如果这不是第一个包含恰好 $k$ 个 $1$ 的极长连续段且 $[p,r]$ 没有改变，这些情况会在统计前面的段的时候算重，为了保证这一段的贡献只会在这一段被统计，我们需要确保 $[p,r]$ 不能和原来一样，所以对于非第一个段需要减去 $\binom{p-l}{k-1}$。  
我们惊讶地发现复杂度是 **$\mathcal{O}(n)$** 的！
::::success[code]
```cpp
#include <bits/stdc++.h>
#define int long long 
using namespace std;
const int N = 5005;
const int mod = 998244353;
int n, k;
string s;
int inv[N], fac[N], pos[N];
int ksm(int a, int b){
    int res = 1;
    while(b){
        if(b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}
void get_fac(){
    fac[0] = inv[0] = 1;
    for(int i = 1; i <= N - 5; i++) fac[i] = fac[i-1] * i % mod; 
    inv[N - 5] = ksm(fac[N-5], mod - 2);
    for(int i = N - 6; i >= 1; i--) inv[i] = inv[i+1] * (i+1) % mod;
}
int C(int a, int b){
    if(b < 0) return 0;
    if(b == 0) return 1;
    if(b > a) return 0;
    return fac[a] * inv[b] % mod * inv[a - b] % mod;
}
signed main(){
    cin.tie(0);
    std::ios::sync_with_stdio(0);
    cin >> n >> k >> s;
    s = ' ' + s;
    get_fac();
    if(k == 0){
        cout << 1 << "\n";
        return 0;
    }
    int m = 0;
    for(int i = 1; i <= n; i++) if(s[i] == '1') pos[++m] = i;
    if(m < k){
        cout << 1 << "\n";
        return 0;
    }
    int ans = 0;
    for(int i = 1; i <= m - k + 1; i++){
        int l = (i == 1) ? 1 : pos[i-1] + 1;
        int r = (i + k - 1 == m) ? n : pos[i+k] - 1;
        if(i == 1)  ans = (ans + C(r - l + 1, k)) % mod;
        else ans = (ans + C(r - l + 1, k) - C(pos[i + k - 1] - l, k - 1) + mod) % mod;
    }
    cout << ans << "\n";
    return 0;
}
```
