#include <bits/stdc++.h>
#define int long long
using namespace std;
const int N = 1100, inf = 1e15;
int n, r, a[N][N], dp[N][N * 5]; //前 i 个格子能凑出来的前 k 大美丽值
struct Node{
    int val;
    int id;
    int rk;
};
bool operator<(const Node &x, const Node &y){
    return x.val < y.val;
}
priority_queue<Node> q;
signed main(){
    int T;
    cin >> T;
    while(T--){
        cin >> n >> r;
        for(int i = 1; i <= n; i++) for(int j = i; j <= n; j++) cin >> a[i][j];
        for(int i = 0; i <= n + 5; i++) for(int k = 1; k <= r + 5; k++) dp[i][k] = -inf;
        dp[0][1] = 0;
        for(int i = 1; i <= n; i++){
            while(!q.empty()) q.pop();
            for(int k = 1; k <= r; k++) q.push(Node{dp[i - 1][k], 0, 114514});
            for(int j = 1; j <= i; j++) q.push(Node{dp[max(j - 2, 0LL)][1] + a[j][i], j, 1});
            for(int k = 1; k <= r; k++){
                Node tmp = q.top();
                q.pop();
                dp[i][k] = tmp.val;
                if(tmp.id) q.push(Node{dp[max(tmp.id - 2, 0LL)][tmp.rk + 1] + a[tmp.id][i], tmp.id, tmp.rk + 1});
            }
        }
        for(int k = 1; k <= r; k++) cout << dp[n][k] << " ";
        cout << "\n";
    }
    return 0;
}
