#include <bits/stdc++.h>
#define int long long
#define eb emplace_back
using namespace std;
const int N = 1e5 + 10;
int a[N], b[N], c[N], p[N], n, m, t, ne[N], cir_cnt, vis[N], ls[N];
vector<int> cir[N];
signed main(){
//	freopen("swap.in", "r", stdin);
//	freopen("swap.out", "w", stdout);
	cin.tie(0);
	std::ios::sync_with_stdio(0);
	cin >> n >> m >> t;
	for(int i = 0; i < n; i++) cin >> a[i], p[i] = i;
	for(int i = 0; i < m; i++) cin >> b[i] >> c[i];
	memcpy(ls, p, sizeof p);
	for(int i = 1; i <= m; i++) swap(ls[(b[i % m] + i) % n], ls[(c[i % m] + i) % n]);
	for(int i = 0; i < n; i++) ne[ls[i]] = (i - m % n + n) % n;
	for(int i = 0; i < n; i++){
		if(!vis[i]){
			int j = i;
			cir[++cir_cnt].eb(i);
			vis[i] = 1;
			while(ne[j] != i){
				j = ne[j];
				vis[j] = 1;
				cir[cir_cnt].eb(j);
			}
		}
	}
	int cnt = t / m;
	for(int i = 1; i <= cir_cnt; i++){
		int len = cir[i].size();
		for(int j = 0; j < len; j++){
			ls[cir[i][(j + cnt) % len]] = cir[i][j];
		}
	}
	for(int i = 1; i <= t % m; i++) swap(ls[(b[i % m] + i) % n], ls[(c[i % m] + i) % n]);
	for(int i = 0; i < n; i++) p[(cnt * (m % n) + i) % n] = ls[i];
	for(int i = 0; i < n; i++) cout << a[p[i]] << " ";
	return 0;
}
