#include <bits/stdc++.h>
#define int long long
#define eb emplace_back
using namespace std;
const int N = 1e5 + 10;
int a[N], b[N], c[N], p[N], n, m, t, ls[N];
struct Node{
	int a[N];
};
Node operator*(const Node &x, const Node &y){
	Node z;
	for(int i = 0; i < n; i++) z.a[i] = y.a[x.a[i]];
	return z;
}
Node ksm(Node a, int b){
	Node res;
	for(int i = 0; i < n; i++) res.a[i] = i;
	while(b){
		if(b & 1) res = res * a;
		a = a * a;
		b >>= 1;
	}
	return res;
